def find_middle(s):
    if not isinstance(s, str):
        return -1

    digits = [int(c) for c in s if c.isdigit()]

    if not digits:
        return -1

    product = 1
    for d in digits:
        product *= d

    product_str = str(product)
    length = len(product_str)
    mid = length // 2

    if length % 2 != 0:
        return int(product_str[mid])
    else:
        middle_two = product_str[mid - 1:mid + 1]
        return int(middle_two)
